import 'package:dbus/dbus.dart';

Future<void> main() async {
  var client = DBusClient.session();
  var object = DBusRemoteObject(client, name: 'com.example.Test', path: DBusObjectPath('/com/example/Test/Object'));
  var version = await object.getProperty('com.example.Test', 'Version', signature: DBusSignature('s')).then((v)=>v.asString());
  print('version: $version');
  await client.close();
}
